// Cost model: scanning touches every byte, so parse cost ~ source length.
function parseCost(source) {
  return source.length; // 1 unit per character (linear)
}

const small = 'const x = 42;'; // a tiny module
const big = small.repeat(100);  // a bundle 100x larger

const costSmall = parseCost(small);
const costBig = parseCost(big);
const ratio = costBig / costSmall;

console.log('small=' + costSmall + ' big=' + costBig + ' ratio=' + ratio);

